Object.assign(names,{
 candidate:['The facts behind every application.','One shared profile. Confirmed experience, clear preferences, and honest unknowns.','CANDIDATE PROFILE'],
 pipeline:['From discovery to a decision.','Sourced research, independent reviewers, and a visible handoff at every step.','SCOUT & COUNCIL']
});
function scoutSummary(){const r=state.pipeline?.runs?.[0];if(!r)return 'Daily task configured. First unattended run still to verify.';return `${r.origin==='scheduled'?'Scheduled':'Interactive'} run: ${r.status} · ${new Date(r.updated).toLocaleString()}. See source coverage in Scout & council.`}
function teamStatus(){const active=state.pipeline?.runs?.some(r=>r.status==='running');return active?'Scout run active · recorded by task':'See Scout & council for actual run history'}
function syncWorkers(){const run=state.pipeline?.runs?.[0];workers[0].status=run?`Last run · ${run.status}`:'Overnight preparation';const queued=state.opportunities.filter(j=>j.council_queue==='queued').length;const reviews=state.pipeline?.councils||[];workers[1].status=queued?`${queued} awaiting review`:reviews.length?`Latest · ${reviews[0].decision||'Awaiting reviewers'}`:'Waiting for evidence'}
function candidateView(){const p=state.pipeline?.profile;if(!p)return '<div class="empty">Candidate profile unavailable.</div>';return `<div class="note">Version ${p.revision} · ${esc(p.provenance)}</div><div class="profile-facts">${p.facts.map(f=>`<article class="queue-card"><div class="eyebrow">CONFIRMED BASELINE</div><h3>${esc(f.label)}</h3><p>${esc(f.value)}</p><small>Source: ${esc(f.source)}</small></article>`).join('')}</div><div class="section-head"><h2>Your search preferences</h2></div><div class="queue">${Object.entries(p.preferences).map(([k,v])=>`<article class="queue-card"><h3>${esc(k[0].toUpperCase()+k.slice(1))}</h3><p>${esc(v)}</p></article>`).join('')}</div><div class="section-head"><h2>Still to confirm</h2></div><div class="note"><ul>${p.unknowns.map(x=>`<li>${esc(x)}</li>`).join('')}</ul><p>Use Your inbox to share a clarification with the team. Missing information never becomes an invented application answer.</p></div><details class="detail-section"><summary>Approval and resume rules</summary><ul>${p.boundaries.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`}
function pipelineView(){const p=state.pipeline;if(!p)return '<div class="empty">Pipeline unavailable.</div>';return `<div class="note">The daily scout runs through your Codex task and saves directly to this workspace. This page displays saved work; opening it does not launch agents. Every send and application still requires your approval. ${p.runs.some(r=>r.origin==="scheduled"&&["completed","partial"].includes(r.status))?"Scheduled run history is recorded below.":"First unattended end-to-end run still to verify."}</div><div class="section-head"><h2>Scout runs</h2></div>${p.runs.length?p.runs.map(r=>`<article class="run-card"><div class="section-head"><h3>${esc(r.origin)} scout</h3>${badge(r.status)}</div><p>${esc(r.summary||'Research in progress. Results have not been finalized.')}</p><small>${new Date(r.started).toLocaleString()} · ${r.imported} new or updated records</small>${r.display_note?`<p class="form-error">${esc(r.display_note)}</p>`:''}<div class="sources">${r.sources.map(s=>`<span>${esc(s.name)}: ${esc(s.status)}</span>`).join('')}</div>${r.sources.length?`<details><summary>Source coverage</summary>${r.sources.map(s=>`<p><b>${esc(s.name)}</b> — ${esc(s.detail)}</p>`).join('')}</details>`:''}</article>`).join(''):'<div class="empty"><p>No pipeline run recorded yet.</p></div>'}<div class="section-head"><h2>Council queue</h2><span class="caption">Five independent assessments → challenge round → final decision</span></div>${table(state.opportunities.filter(j=>['queued','reviewing'].includes(j.council_queue)))}<div class="section-head"><h2>Council review history</h2></div>${p.councils.length?p.councils.map(c=>`<article class="run-card"><div class="section-head"><h3>${esc(c.opportunity_snapshot.company)}</h3>${badge(c.current?(c.decision||'Pending evaluation'):'Superseded evidence')}</div><p>${esc(c.opportunity_snapshot.title)}</p><p class="caption">Independent round: ${c.round1.length}/5 · Final round: ${c.round2.length}/5 · Candidate version ${c.profile_snapshot.revision}</p><button class="secondary" data-council="${c.id}">Read debate and votes →</button></article>`).join(''):'<div class="empty"><p>No versioned review recorded yet. Earlier trial findings remain in their opportunity records.</p></div>'}`}
function researchDetail(j){if(!j.research)return '';return `<details class="detail-section" style="margin-top:18px"><summary>Scout evidence · ${esc(j.scout_status)}</summary><p class="caption">Last research check: ${new Date(j.research.checked_at).toLocaleString()}</p>${Object.entries(j.research.gates).map(([k,g])=>`<div class="vote"><b>${esc(k[0].toUpperCase()+k.slice(1))}</b> ${badge(g.status)}<p>${esc(g.reason)}</p></div>`).join('')}${j.research.deadline_note?`<div class="note"><b>Deadline</b><p>${esc(j.research.deadline_note)}</p></div>`:""}<h3 style="margin-top:16px">Required skills</h3><p>${esc(j.research.required_skills)}</p><h3 style="margin-top:16px">Evidence sources</h3>${j.research.evidence.map(e=>`<p><a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.id)} · ${esc(e.type.replaceAll('_',' '))} ↗</a><br>${esc(e.note)}</p>`).join('')}</details>`}
function showCouncil(id){const c=state.pipeline.councils.find(x=>x.id===id);if(!c)return;modal(`<div class="eyebrow">FIVE-PERSON COUNCIL</div><h2 class="detail-title">${esc(c.opportunity_snapshot.company)}</h2>${badge(c.current?(c.decision||'Pending evaluation'):'Superseded evidence')}<p class="note">All five final reviewers must approve. Missing evidence can keep a unanimous recommendation on hold. Council approval never authorizes an application.</p>${[1,2].map(round=>`<h3>${round===1?'Independent assessments':'Challenge round — final votes'}</h3>${c['round'+round].length?c['round'+round].map(v=>`<div class="vote"><b>${esc(v.role)}</b> ${badge(v.vote)}<p>${esc(v.reason)}</p><small>Sources: ${v.evidence_ids.map(id=>{const e=c.opportunity_snapshot.research.evidence.find(e=>e.id===id);return `<a href="${esc(e.url)}" target="_blank" rel="noopener noreferrer">${esc(e.type.replaceAll("_"," "))} ↗</a>`}).join(", ")}</small></div>`).join(''):'<p>Awaiting reviewers.</p>'}`).join('')}<div class="actions"><button class="secondary" data-job="${c.opportunity_id}">Open opportunity →</button></div>`)}
document.addEventListener('click',e=>{const el=e.target.closest('[data-council]');if(el)showCouncil(el.dataset.council)});
// Refresh saved agent work without interrupting a form or a review dialog.
setInterval(async()=>{if(document.hidden||$('#dialog').open||['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName))return;try{const next=await api('/api/state');if(!state||JSON.stringify(next.pipeline)!==JSON.stringify(state.pipeline)||JSON.stringify(next.opportunities)!==JSON.stringify(state.opportunities)||JSON.stringify(next.approvals)!==JSON.stringify(state.approvals)){state=next;render()}}catch{}},8000);
function priorCouncilDetail(j){return j.prior_council?.length?`<details class="detail-section"><summary>Earlier council findings · preserved history</summary><p class="caption">These findings preceded the current evidence or profile. They are not current approvals.</p>${j.prior_council.map(c=>`<h3>${esc(c.council)}</h3>${c.votes.map(v=>`<div class="vote"><b>${esc(v.role)}</b> ${badge(v.vote)}<p>${esc(v.reason)}</p></div>`).join('')}`).join('')}</details>`:''}

